def generate_batch19() -> List[Dict]:
    """生成 batch19 恢复与睡眠 chunks"""
    chunks = []
    for item in RECOVERY_DATA:
        chunks.append(make_chunk(
            category="recovery",
            subcategory="recovery_sleep",
            title=item["title"],
            content=item["content"],
            keywords=item["keywords"],
        ))
    return chunks


if __name__ == "__main__":
    chunks = generate_batch19()
    print(f"生成 {len(chunks)} 个恢复与睡眠 chunks")

    output_dir = os.path.join(os.path.dirname(__file__), "output")
    os.makedirs(output_dir, exist_ok=True)
    with open(os.path.join(output_dir, "batch19.json"), "w", encoding="utf-8") as f:
        json.dump(chunks, f, ensure_ascii=False, indent=2)
    print(f"已保存到 output/batch19.json")
